from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
REQ=json.loads((R/'src/requirements.json').read_text());SCENES=[]
DDPM='https://arxiv.org/abs/2006.11239';LDM='https://arxiv.org/abs/2112.10752';CFG='https://arxiv.org/abs/2207.12598';DIT='https://arxiv.org/abs/2212.09748';LLADA='https://arxiv.org/abs/2502.09992'
def eq(s):return '<div class="math">'+html.escape(s)+'</div>'
def p(s):return '<p>'+s+'</p>'
def img(name,caption='',step=1):return f'<figure data-step="{step}"><img src="assets/{name}" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>'
def flow(items):
    n=len(items);w=1050;bw=min(285,(w-(n-1)*55)/n);gap=(w-n*bw)/max(1,n-1);s='<svg role="img" aria-label="'+html.escape(' then '.join(a[0] for a in items))+'" viewBox="0 0 1100 230"><defs><marker id="tip" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#566171"/></marker></defs>'
    for i,(title,sub,color) in enumerate(items):
        x=25+i*(bw+gap)
        s+=f'<rect x="{x}" y="55" width="{bw}" height="120" rx="8" fill="{color}12" stroke="{color}" stroke-width="2"/><text x="{x+bw/2}" y="105" text-anchor="middle" fill="{color}" font-size="28" font-family="Avenir Next, sans-serif">{html.escape(title)}</text><text x="{x+bw/2}" y="145" text-anchor="middle" fill="#566171" font-size="21" font-family="Avenir Next,sans-serif">{html.escape(sub)}</text>'
        if i<n-1:s+=f'<path d="M{x+bw+5},115 H{x+bw+gap-10}" fill="none" stroke="#566171" stroke-width="2" marker-end="url(#tip)"/>'
    return s+'</svg>'
def diagram(items):return '<div class="diagram">'+flow(items)+'</div>'
def cols(*bits):return '<div class="panels">'+''.join(bits)+'</div>'
def code(s):return '<pre>'+html.escape(s)+'</pre>'
def demo(kind):return f'<div class="demo" data-demo="{kind}"></div>'
def steps(xs):return '<div class="steps">'+''.join(f'<div class="step'+(' repeated-equation' if x in xs[:i] else '')+f'" data-step="{i+1}"><span class="step-no">{i+1:02}</span><div>{x}</div></div>' for i,x in enumerate(xs) if x)+'</div>'
def add(n,visual,lines,note,question='',answer='',source=DDPM,layout='split',assets=None):
    r=REQ[n-1];assert len(lines)==r['planned_builds'],(n,len(lines),r['planned_builds'])
    section=next(k for k,a,b in [('Applications',1,10),('Corruption',11,20),('Learning',21,31),('Generation',32,39),('Architecture',40,46),('Conditioning',47,54),('Evidence and language',55,60)] if a<=n<=b)
    SCENES.append(dict(id=r['id'],number=n,title=r['title'].replace('“','').replace('”','').replace('Parameterize','Parameterise'),section=section,builds=len(lines),learning_goal=question or r['title'],visual_description=html.unescape(__import__('re').sub('<[^>]*>',' ',visual))[:800],visual=visual,steps=lines,narration=note,question=question,answer=answer,source=source,assets=assets or [],layout=layout,routes=['full','compressed']))
B='#245EDB';A='#9A5700';T='#0F766E';P='#793DB5';E='#BE123C'
add(1,img('ddpm.png','Published unconditional samples · Ho, Jain & Abbeel (2020)'),[p('What would we need to create another example?')], 'Give students ten seconds to inspect faces, rooms and animals. These are published samples, not photographs. Ask what inputs each task might require. Our question is how learning to remove noise can define a generator.', 'What was the system given?','Unconditional generation needs a random starting state; conditional tasks also receive information such as text or observed pixels.',source='https://hojonathanho.github.io/diffusion/',layout='gallery',assets=['ddpm'])
add(2,cols(*[img(f'ldm-{i}.png',f'Published sample {i}',1 if i==1 else 2) for i in range(1,5)]),[p('“A basket full of cherries”'),p('Several different images can fit the same description.')], 'Read the source prompt above the column, then reveal the diversity question. These are different published samples, not a documented fixed-seed experiment. Hold this prompt and sample identity fixed when returning to text conditioning.', 'Which sample is the correct target?','There need not be one unique correct image; the target is a conditional distribution.',source='https://ommer-lab.com/research/latent-diffusion-models/',layout='gallery',assets=['ldm-samples'])
add(3,img('gligen.png','GLIGEN · supplied boxes and text, followed by published outputs'),[p('A condition can specify <strong>where</strong> objects should appear.'),p('The layout still leaves choices about appearance.')], 'Point to the boxes before discussing output images. The project supplies grounding layouts and captions. Do not claim matched seeds or perfect compositional adherence. Later we distinguish spatial conditions from text features.', 'Do boxes determine every pixel?','No. They constrain location while appearance remains uncertain.',source='https://gligen.github.io/',layout='gallery',assets=['gligen'])
add(4,cols(img('repaint-input.png','Observed pixels + blue unknown region'),img('repaint-outputs.png','Five sampled fillings of this same input',2)),[p('We observe part of the face; the blue region is missing.'),p('Several plausible faces can match those visible pixels.')], 'Use the first row from the same RePaint comparison. The final five columns are distinct samples, not successive timesteps; the middle columns of the original are denoising states. Return to this exact face in Scene 54.', 'Must a plausible completion recover the original?','No. It samples a possible explanation, not necessarily the image that was hidden.',source='https://github.com/andreas128/RePaint',layout='gallery',assets=['repaint-input','repaint-outputs'])
add(5,cols(img('sdedit-input.png','SDEdit · supplied bedroom strokes'),img('sdedit-output-1.png','Published output 1',2),img('sdedit-output-2.png','Published output 2',2)),[p('Start from rough colour strokes.'),p('The starting noise level controls how strongly the strokes guide the result.')], 'SDEdit corrupts an input and uses a learned denoising process. The model is not trained anew for every sketch, and preserving every supplied pixel is not its promise. Invite predictions before revealing the output rows.', 'What changes with stronger initial noise?','The input can exert less influence; a plausible image need not preserve exact strokes.',source='https://sde-image-editing.github.io/',layout='gallery',assets=['sdedit-input','sdedit-output'])
add(6,img('sr3-top.png','SR3 source comparison · bicubic / regression / sampled SR3 / paired reference'),[p('The low-resolution image leaves fine detail uncertain.'),p('A realistic detail is one possible explanation of the observation.')], 'Keep the source labels. This asset supplies an actual paired reference. Bicubic is an interpolation baseline; regression and diffusion differ in how they represent missing detail. Avoid claiming that realism verifies what was measured.', 'Does a realistic eyelash establish that it was observed?','No; evaluate against held-out references and the observation model.',source='https://iterative-refinement.github.io/',layout='gallery',assets=['sr3-top'])
add(7,img('control-pair.png','ControlNet · Canny edges as condition; generated bird'),[p('An edge map records the structure of an image.'),p('We can use that structure to guide a generated image.')], 'Identify the edge map explicitly. A control module gives one way to inject spatial conditions; it is not part of every diffusion model. The scene makes a connection to dense vision before introducing a new backbone.', 'Which part is the condition?','The edge map; the colourful image is a generated output.',source='https://github.com/lllyasviel/ControlNet',layout='gallery',assets=['control-pair'])
add(8,cols(img('dreambooth-input.png','Reference subject images: model adaptation'),img('dreambooth-output.png','New prompts to the adapted model',2)),[p('Use reference images to adapt the model to this subject.'),p('Then ask for the subject in a new setting.')], 'The references are used during subject-specific adaptation. Do not draw them as an unchanged model input at each inference step. Ask which identity features remain recognisable when the context changes.', 'When do the reference images enter?','During adaptation; prompts condition the adapted model during generation.',source='https://dreambooth.github.io/',layout='gallery',assets=['dreambooth-input','dreambooth-output'])
add(9,img('sat.png','DiffusionSat · source metadata and generated satellite imagery'),[p('Coordinates, metadata and observations can condition a model.'),diagram([('Observed','partial signal',B),('Missing','uncertain region',A),('Candidates','possible research task',T)])], 'The left evidence is a published DiffusionSat result. The small diagram is a possible lab research task, not an accomplished lab result. Ask how measurement consistency, held-out tests and uncertainty would be assessed.', 'What would establish scientific usefulness?','Validation against withheld measurements and an explicit observation model, beyond visual plausibility.',source='https://www.samarkhanna.com/DiffusionSat/',assets=['sat'])
add(10,diagram([('Randomness','unconditional',A),('Condition c','text / map / pixels',P),('New sample','x drawn from model',B)]),[eq(r'p_\theta(x\mid c)'),p('How do we build training examples, choose a target and generate a sample?')], 'After concrete applications, introduce the abstraction. c is omitted for unconditional generation. We will first implement one historical DDPM formulation; gallery methods need not share every detail.', 'What three questions remain?','How to create training examples, what to predict, and how to use the prediction to sample.')
add(11,cols(img('autoencoder_vs_vae.svg','Lecture I · autoencoder and VAE recap'),img('gan_game.svg','Lecture I · GAN recap',1)),[p('In Lecture I, we drew a latent and passed it through a generator.'),diagram([('Noise','xT',A),('Small steps','shared denoiser',T),('Data','x0',B)])], 'Reconnect to the actual course diagrams. A VAE has a prior and decoder, a GAN an induced distribution through a generator. Diffusion parameterises a different chain of transformations, not a universal improvement claim.')
