add(52,diagram([('εu','unconditional',A),('εc − εu','conditional direction',P),('εcfg','combined prediction',T)]),[eq(r'\epsilon_{cfg}=\epsilon_u+s(\epsilon_c-\epsilon_u)'),p('s=0: unconditional. s=1: ordinary conditional.'),p('s>1: extrapolation; two logical evaluations may be batched.')], 'Some sources use w=s-1. Our scale s multiplies conditional minus unconditional. This needs no separately trained classifier; the difference is not a literal pixel edit mask.',source=CFG,layout='wide')
